// Accounts whose edits are not counted as translator work.
const EXCLUDE_EMAILS = 'support@lokalise.co,support@lokali.se,maria@efuturemedia.com,kseniya.krasovskaya@efuturemedia.com';
const WINDOW_HOURS = 168;
// When the webhook collector went live; before this there is no event history.
const COLLECTION_START = 1787647800;
const TZ = 'Europe/Madrid';

const now = Math.floor(Date.now() / 1000);
const since = now - WINDOW_HOURS * 3600;
let windowLabel = WINDOW_HOURS + 'h';
if (WINDOW_HOURS % 24 === 0) { const dys = WINDOW_HOURS / 24; windowLabel = dys + (dys === 1 ? ' day' : ' days'); }

const excl = [];
for (const e of EXCLUDE_EMAILS.toLowerCase().split(',')) { const v = e.trim(); if (v) { excl.push(v); } }

function stamp(ts) {
  const d = new Date(ts * 1000);
  return d.toLocaleString('en-GB', { timeZone: TZ, day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false });
}
function num(n) { return Number(n).toLocaleString('en-US'); }
function isPseudo(iso) { const s = (iso || '').toLowerCase(); return s === 'pst' || s.indexOf('pseudo') >= 0; }

const projects = ($('Fetch Lokalise Projects').first().json || {}).projects || [];
const pmap = {};
let productCount = 0;
for (const p of projects) {
  const st = p.statistics || {};
  const kt = (st.keys_total === undefined || st.keys_total === null) ? 0 : st.keys_total;
  pmap[String(p.project_id)] = { name: p.name, base: String(p.base_language_iso || 'en').toLowerCase(), keys_total: kt };
  if (kt) { productCount++; }
}

const byProject = {};
let events = 0;
for (const it of $input.all()) {
  const r = it.json || {};
  const ts = parseInt(r.event_ts, 10) || 0;
  if (ts < since) { continue; }
  const pid = String(r.project_id || '');
  const meta = pmap[pid] || { name: r.project_name || pid, base: 'en', keys_total: null };
  const iso = String(r.language_iso || '').toLowerCase();
  if (!iso || iso === meta.base || isPseudo(iso)) { continue; }
  const em = String(r.user_email || '').toLowerCase();
  if (excl.indexOf(em) >= 0) { continue; }
  events++;
  if (!byProject[pid]) { byProject[pid] = { name: meta.name, keys_total: meta.keys_total, langs: {}, all: {} }; }
  const b = byProject[pid];
  if (!b.langs[iso]) { b.langs[iso] = {}; }
  b.langs[iso][r.key_id] = 1;
  b.all[r.key_id] = 1;
}

const rows = [];
for (const pid of Object.keys(byProject)) {
  const b = byProject[pid];
  const langs = [];
  for (const l of Object.keys(b.langs)) { langs.push({ lang: l, n: Object.keys(b.langs[l]).length }); }
  if (!langs.length) { continue; }
  langs.sort(function (a, c) { if (c.n !== a.n) { return c.n - a.n; } return a.lang.localeCompare(c.lang); });
  rows.push({ name: b.name, keys_total: b.keys_total, distinct: Object.keys(b.all).length, langs: langs });
}
rows.sort(function (a, b) {
  return a.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase().localeCompare(b.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase());
});

let grand = 0;
for (const r of rows) { for (const l of r.langs) { grand += l.n; } }

let text = '*Lokalise — keys edited in the last ' + windowLabel + '*\n';
text += '_' + stamp(since) + ' → ' + stamp(now) + ' (Madrid). Translation updates only — status changes, source language, pseudo-language and admin accounts excluded._\n\n';

if (rows.length === 0) {
  text += 'No translation updates in the window.\n';
} else {
  text += '*' + num(grand) + ' key edits across ' + rows.length + ' of ' + productCount + ' products*\n\n';
  for (const r of rows) {
    const parts = [];
    for (const l of r.langs) { parts.push(l.lang + ' ' + num(l.n)); }
    const totalTxt = (r.keys_total === null || r.keys_total === undefined) ? 'unknown' : num(r.keys_total);
    text += '• *' + r.name + '* — ' + num(r.distinct) + ' keys touched of ' + totalTxt + ' in the product\n';
    text += '   ' + parts.join('  ·  ') + '\n';
  }
  text += '\n' + (productCount - rows.length) + ' product(s) with no edits.\n';
}

if (since < COLLECTION_START) {
  text += '\n_Event collection started ' + stamp(COLLECTION_START) + ', so this window is not yet complete._';
}
if (text.length > 3800) { text = text.slice(0, 3740) + '\n… truncated, see the full run in n8n.'; }

return [{ json: { report: text, products_with_edits: rows.length, products_total: productCount, grand_total: grand, events_counted: events } }];

